$&quot; responses = [completion[0][&quot;content&quot;] for completion in completions] matches = [re.match(pattern, r) for r in responses] return [0.5 if match else 0.0 for match in matches]# Reward function with a softer check for the XML format.def soft_format_reward_func(completions, **kwargs) -&gt; list[float]: pattern = r&quot;&lt;reasoning&gt;.*?&lt;/reasoning&gt;\s*&lt;answer&gt;.*?&lt;/answer&gt;&quot; responses = [completion[0][&quot;content&quot;] for completion in completions] matches = [re.match(pattern, r) for r in responses] return [0.5 if match else 0.0 for match in responses]# Function to count specific XML tokens and award a small reward for each.def count_xml(text) -&gt; float: count = 0.0 if text.count(&quot;&lt;reasoning&gt;
